set current_status = 2,
    update_time = now(),
    current_processor_id = null
where copywriting_approval_flow_id = #{copywritingApprovalFlowId}
  and copywriting_id = #{copywritingId}
  and current_status = 0





        and current_processor_id = #{currentProcessorId}
        and exists (
